public class Main {
    public static void main(String[] args) {
        for (int row = 1; row <= 2; row++) {
            for (int column = 1; column <= 3; column++) {
                System.out.print(row * column + " ");
            }
            System.out.println();
        }
        int[] marks = {72, 85, 91};
        int total = 0;
        for (int mark : marks) {
            total += mark;
        }
        System.out.println(total);
    }
}
